  1	package hotel.reservations;
  2	
  3	import hotel.documents.BookingReceipt;
  4	import hotel.documents.Document;
  5	import hotel.documents.InvoiceDocument;
  6	import hotel.documents.ReservationReceipt;
  7	import hotel.messages.EmailSender;
  8	import hotel.rooms.Room;
  9	import hotel.rooms.Rooms;
 10	import java.math.BigDecimal;
 11	
 12	public final class ReservationService {
 13	
 14	    static final String HOTEL_NAME = "Pousada Maré Alta";
 15	
 16	    private final Rooms rooms;
 17	    private final ReservationStore store;
 18	    private final PriceCalculator priceCalculator;
 19	    private final EmailSender emailSender;
 20	
 21	    public ReservationService(
 22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 23	        this.rooms = rooms;
 24	        this.store = store;
 25	        this.priceCalculator = priceCalculator;
 26	        this.emailSender = emailSender;
 27	    }
 28	
 29	    public synchronized Reservation create(NewReservation request) {
 30	        if (!request.checkOut().isAfter(request.checkIn())) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 32	        }
 33	        if (request.guests() < 1) {
 34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 35	        }
 36	        Room room = rooms.find(request.roomNumber())
 37	                .orElseThrow(() -> new HotelException(
 38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 39	        if (request.guests() > room.capacity()) {
 40	            throw new HotelException(
 41	                    ErrorCode.CAPACITY_EXCEEDED,
 42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 43	        }
 44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 45	            throw new HotelException(
 46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 47	        }
 48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 49	        return store.add(request, price);
 50	    }
 51	
 52	    public Reservation find(long reservationId) {
 53	        return store.find(reservationId)
 54	                .orElseThrow(() -> new HotelException(
 55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 56	    }
 57	
 58	    public synchronized Reservation confirm(long reservationId) {
 59	        Reservation reservation = find(reservationId);
 60	        if (reservation.status() != ReservationStatus.PENDING) {
 61	            throw notAllowed(reservation, "confirm");
 62	        }
 63	        reservation.confirmPayment();
 64	        store.update(reservation);
 65	        Document document = createDocument(reservation, roomOf(reservation));
 66	        emailSender.send(
 67	                reservation.guest().email(),
 68	                "Reserva confirmada - " + HOTEL_NAME,
 69	                confirmationEmailBody(reservation, document));
 70	        return reservation;
 71	    }
 72	
 73	    public synchronized Reservation cancel(long reservationId) {
 74	        Reservation reservation = find(reservationId);
 75	        if (reservation.status() != ReservationStatus.PENDING
 76	                && reservation.status() != ReservationStatus.CONFIRMED) {
 77	            throw notAllowed(reservation, "cancel");
 78	        }
 79	        BigDecimal refund = switch (reservation.ratePlan()) {
 80	            case STANDARD -> reservation.amountPaid();
 81	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 82	        };
 83	        reservation.cancel(refund);
 84	        store.update(reservation);
 85	        return reservation;
 86	    }
 87	
 88	    public synchronized Reservation checkIn(long reservationId) {
 89	        Reservation reservation = find(reservationId);
 90	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 91	            throw notAllowed(reservation, "check in");
 92	        }
 93	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 94	        store.update(reservation);
 95	        return reservation;
 96	    }
 97	
 98	    public synchronized Document checkOut(long reservationId) {
 99	        Reservation reservation = find(reservationId);
100	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
101	            throw notAllowed(reservation, "check out");
102	        }
103	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
104	        store.update(reservation);
105	        return createDocument(reservation, roomOf(reservation));
106	    }
107	
108	    public Document receiptCopy(long reservationId) {
109	        Reservation reservation = find(reservationId);
110	        if (!reservation.isPaid()) {
111	            throw notAllowed(reservation, "issue a receipt for");
112	        }
113	        return createDocument(reservation, roomOf(reservation));
114	    }
115	
116	    private static Document createDocument(Reservation reservation, Room room) {
117	        if (reservation.guest().companyCnpj() != null) {
118	            return new InvoiceDocument(reservation, room);
119	        } else if (reservation.guest().guestPassport() != null) {
120	            return new BookingReceipt(reservation, room);
121	        } else {
122	            return new ReservationReceipt(reservation, room);
123	        }
124	    }
125	
126	    private Room roomOf(Reservation reservation) {
127	        return rooms.find(reservation.roomNumber()).orElseThrow();
128	    }
129	
130	    private static String confirmationEmailBody(Reservation reservation, Document document) {
131	        return "Olá, " + reservation.guest().name() + "!\n\n"
132	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
133	                + document.text() + "\n"
134	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
135	                + "Até breve!\n";
136	    }
137	
138	    private static HotelException notAllowed(Reservation reservation, String operation) {
139	        return new HotelException(
140	                ErrorCode.OPERATION_NOT_ALLOWED,
141	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
142	    }
143	}
  1	package hotel.documents;
  2	
  3	import hotel.reservations.Reservation;
  4	import hotel.rooms.Room;
  5	import hotel.rooms.RoomType;
  6	import java.math.BigDecimal;
  7	import java.time.LocalDate;
  8	
  9	public record ReservationReceipt(
 10	        String title,
 11	        long reservationId,
 12	        String guestName,
 13	        String guestCpf,
 14	        int roomNumber,
 15	        RoomType roomType,
 16	        LocalDate checkIn,
 17	        LocalDate checkOut,
 18	        int nights,
 19	        BigDecimal subtotal,
 20	        BigDecimal discount,
 21	        BigDecimal total)
 22	        implements Document {
 23	
 24	    public ReservationReceipt(Reservation reservation, Room room) {
 25	        this(
 26	                "Comprovante de reserva",
 27	                reservation.id(),
 28	                reservation.guest().name(),
 29	                reservation.guest().cpf(),
 30	                room.number(),
 31	                room.type(),
 32	                reservation.checkIn(),
 33	                reservation.checkOut(),
 34	                reservation.price().nights(),
 35	                reservation.price().subtotal(),
 36	                reservation.price().discount(),
 37	                reservation.price().total());
 38	    }
 39	
 40	    @Override
 41	    public String text() {
 42	        StringBuilder text = new StringBuilder();
 43	        text.append(title).append(" nº ").append(reservationId).append('\n');
 44	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
 45	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 46	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 47	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 48	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 49	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 50	        if (discount.signum() > 0) {
 51	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 52	        }
 53	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
 54	        return text.toString();
 55	    }
 56	}
 57	package hotel.reservations;
 58	
 59	import hotel.rooms.Room;
 60	import java.math.BigDecimal;
 61	import java.math.RoundingMode;
 62	import java.time.LocalDate;
 63	import java.time.Month;
 64	
 65	/**
 66	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 67	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 68	 * (half-even) at every step.
 69	 */
 70	public final class PriceCalculator {
 71	
 72	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 73	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 74	
 75	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 76	        int nights = 0;
 77	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 78	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 79	            subtotal = subtotal.add(nightPrice(room, night));
 80	            nights++;
 81	        }
