 65	/**
 66	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 67	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 68	 * (half-even) at every step.
 69	 */
 70	public final class PriceCalculator {
 71	
 72	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 73	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 74	
 75	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 76	        int nights = 0;
 77	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 78	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 79	            subtotal = subtotal.add(nightPrice(room, night));
 80	            nights++;
 81	        }
 82	        BigDecimal discount = switch (ratePlan) {
 83	            case STANDARD -> cents(BigDecimal.ZERO);
 84	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 85	        };
 86	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 87	    }
 88	
 89	    BigDecimal nightPrice(Room room, LocalDate night) {
 90	        BigDecimal nightlyRate = room.nightlyRate();
 91	        if (isHighSeason(night)) {
 92	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 93	        }
 94	        return cents(nightlyRate);
 95	    }
 96	
 97	    /** High season: from December 15 to the end of February, and the whole of July. */
 98	    static boolean isHighSeason(LocalDate date) {
 99	        Month month = date.getMonth();
100	        return month == Month.JANUARY
101	                || month == Month.FEBRUARY
102	                || month == Month.JULY
103	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
104	    }
105	
106	    static BigDecimal cents(BigDecimal value) {
107	        return value.setScale(2, RoundingMode.HALF_EVEN);
108	    }
109	}
